query = {"refund": 2, "weather": 0}
keys = {
    "policy": {"refund": 3, "weather": 0},
    "forecast": {"refund": 0, "weather": 4},
}

def dot(a, b):
    return sum(a[k] * b[k] for k in a)

scores = {name: dot(query, key) for name, key in keys.items()}
print(scores)
print(max(scores, key=scores.get))
